package version

import "testing"

func TestOwned(t *testing.T) {
	for line, want := range map[string]bool{
		GoHeaderLine:   true,
		YAMLHeaderLine: true,
		"// Code generated by coralogix-operator-codegen v0.1.0-beta.3. DO NOT EDIT.": true, // an older header
		"# Code generated by coralogix-operator-codegen v0.1.0-beta.1. DO NOT EDIT.":  true,
		"// Code generated by coralogix-operator-codegen v. DO NOT EDIT.":             false,
		"// Code generated by controller-gen. DO NOT EDIT.":                           false,
		"// Copyright 2026 Coralogix Ltd.":                                            false,
	} {
		if got := Owned(line); got != want {
			t.Errorf("Owned(%q) = %v, want %v", line, got, want)
		}
	}
}
